def _set_attr(tag: str, name: str, value: str) -> str:
    pattern = re.compile(
        r"\s+" + re.escape(name) + r'\s*=\s*(["\']).*?\1',
        re.I | re.S,
    )
    tag = pattern.sub("", tag)
    if not tag.endswith(">"):
        raise HomeCounterError("INVALID_TAG:" + name)
    return tag[:-1] + ' %s="%s">' % (name, html.escape(value, quote=True))

