    if (!doc.querySelector('.catalog-grid')) throw Error('Missing catalog grid');
    const records = new Map();
    const cards = Array.from(doc.querySelectorAll('article.catalog-card'));
    doc.querySelectorAll('a[data-ua-card]').forEach(node => {
