      if (!last) return;
      document.querySelectorAll('.stage-card[data-stage]').forEach(card => {
        const key = aliases[card.getAttribute('data-stage')];
        if (!key) return;
        const label = card.querySelector('.stage-copy em') || card.querySelector('em');
