          if(obeschanie && obeschanie.catch) obeschanie.catch(function(){ /* браузер запретил — остаётся кнопка */ });
        }
      }, {threshold:[0, 0.35, 0.5, 0.75, 1]});
      for(var rn=0; rn<roliki.length; rn++) nablyudatel.observe(roliki[rn]);
    }
    document.addEventListener('visibilitychange', function(){
      if(document.hidden){ for(var rp=0; rp<roliki.length; rp++){ try{ roliki[rp].pause(); }catch(err){} } }
    });
  }

  /* карточка: поделиться */
  var knopka = document.querySelector('.share-button');
  if(knopka){
    var menyu=document.querySelector('.share-menu');
