    /* закрытие: крестик, нажатие вне окна, выбор пункта, прокрутка, Escape */
    var krestik=document.querySelector('.share-zakryt');
    if(krestik) krestik.addEventListener('click', function(s2){ s2.stopPropagation(); zakryt_menyu(); });
    if(menyu){
      var punkty=menyu.querySelectorAll('a');
      for(var pk=0;pk<punkty.length;pk++) punkty[pk].addEventListener('click', zakryt_menyu);
      menyu.addEventListener('click', function(s3){ s3.stopPropagation(); });
