/* ===== UA-FIXCHIP-V2: активное состояние чипов панели фильтров =================
   Класс active стоит в разметке статически на кнопке «Все». Этот блок
   переносит его на выбранный этап и снимает с остальных.
   Механизм скрытия карточек не затрагивается.
   =================================================================== */
(function(){
  try{
    function tekushchiy(){
      var par = new URLSearchParams(location.search);
      var st = par.get('stage') || par.get('f') || 'all';
      var karta = {kiev:'kiev', gruzia:'georgia', georgia:'georgia',
                   more:'sea', sea:'sea', korea:'korea', all:'all', vse:'all'};
      return karta[st] || st;
    }
    function postavit(){
      var vybran = tekushchiy();
      var chipy = document.querySelectorAll('[data-f]');
      var aktivnyh = 0, nazhatyh = 0;
      for (var i = 0; i < chipy.length; i++){
        var c = chipy[i];
        var svoy = (c.getAttribute('data-f') || '') === vybran;
        if (svoy){
          c.classList.add('active');
          c.setAttribute('aria-pressed', 'true');
          aktivnyh++; nazhatyh++;
        } else {
          c.classList.remove('active');
          c.setAttribute('aria-pressed', 'false');
        }
      }
      return {vybran: vybran, chipov: chipy.length,
              aktivnyh: aktivnyh, nazhatyh: nazhatyh};
    }
    function zapusk(){
      postavit();
      setTimeout(postavit, 300);
      setTimeout(postavit, 900);
      document.addEventListener('click', function(){ setTimeout(postavit, 60); }, true);
      window.addEventListener('popstate', function(){ setTimeout(postavit, 60); });
      window.addEventListener('hashchange', function(){ setTimeout(postavit, 60); });
    }
    if (document.readyState === 'loading'){
      document.addEventListener('DOMContentLoaded', zapusk);
    } else { zapusk(); }
  }catch(e){}
})();
/* ===== конец UA-FIXCHIP-V2 ===== */

/* ===== UA-FIXCLICK-V1: клик по чипу внутри каталога ==========================
   Родной обработчик вешает карточкам inline display:none и прячет все,
   потому что сопоставляет data-f с data-stage. Здесь inline-стиль
   снимается, а решение остаётся за уже работающим CSS-правилом
   html[data-etap-filtr] .catalog-card:not([data-stage=...]).
   ================================================================= */
(function(){
  try{
    var KARTA = {kiev:'kiev', gruzia:'georgia', georgia:'georgia',
                 more:'sea', sea:'sea', korea:'korea', all:'all', vse:'all'};

    function normalizovat(z){
      z = (z || '').toLowerCase();
      return KARTA[z] || z;
    }

    function snyat_inline(){
      var karty = document.querySelectorAll('.catalog-card');
      for (var i = 0; i < karty.length; i++){
        if (karty[i].style && karty[i].style.display){
          karty[i].style.removeProperty('display');
        }
        if (karty[i].hasAttribute('hidden')){
          karty[i].removeAttribute('hidden');
        }
      }
      return karty.length;
    }

    function vidimyh(){
      var karty = document.querySelectorAll('.catalog-card'), n = 0;
      for (var i = 0; i < karty.length; i++){
        var st = window.getComputedStyle ? window.getComputedStyle(karty[i]) : null;
        if (st && (st.display === 'none' || st.visibility === 'hidden')) continue;
        n++;
      }
      return n;
    }

    function pokazano(){
      var n = vidimyh();
      var vse = document.querySelectorAll('a,span,button,div,li,p,em,b,strong,small');
      for (var i = 0; i < vse.length; i++){
        var e = vse[i];
        if (e.children && e.children.length > 0) continue;
        var t = (e.textContent || '').replace(/\s+/g, ' ').trim();
        if (/^(Показано|Показанo|Показуємо)\s*:?\s*\d+$/.test(t)){
          var novoe = t.replace(/\d+/, String(n));
          if (t !== novoe) e.textContent = novoe;
        }
      }
      return n;
    }

    function chipy(vybran){
      var spisok = document.querySelectorAll('[data-f]');
      for (var i = 0; i < spisok.length; i++){
        var c = spisok[i];
        var svoy = normalizovat(c.getAttribute('data-f')) === vybran;
        if (svoy){ c.classList.add('active'); c.setAttribute('aria-pressed','true'); }
        else { c.classList.remove('active'); c.setAttribute('aria-pressed','false'); }
      }
    }

    function primenit(vybran, menyat_adres){
      vybran = normalizovat(vybran || 'all');
      if (vybran === 'all'){
        document.documentElement.removeAttribute('data-etap-filtr');
      } else {
        document.documentElement.setAttribute('data-etap-filtr', vybran);
      }
      chipy(vybran);
      snyat_inline();
      if (menyat_adres && window.history && history.replaceState){
        var adres = location.pathname + (vybran === 'all'
          ? '' : ('?f=' + vybran + '&stage=' + vybran));
        try{ history.replaceState(null, '', adres); }catch(e){}
      }
      pokazano();
      // родной обработчик может отработать позже — повторяем
      setTimeout(function(){ snyat_inline(); pokazano(); }, 60);
      setTimeout(function(){ snyat_inline(); pokazano(); }, 250);
      setTimeout(function(){ snyat_inline(); pokazano(); }, 600);
    }

    function iz_adresa(){
      var par = new URLSearchParams(location.search);
      return normalizovat(par.get('stage') || par.get('f') || 'all');
    }

    function zapusk(){
      primenit(iz_adresa(), false);
      document.addEventListener('click', function(sob){
        var el = sob.target;
        while (el && el !== document.documentElement && !el.hasAttribute('data-f')){
          el = el.parentElement;
        }
        if (!el || !el.hasAttribute('data-f')) return;
        primenit(el.getAttribute('data-f'), true);
      }, true);
      window.addEventListener('popstate', function(){ primenit(iz_adresa(), false); });
      window.addEventListener('hashchange', function(){ primenit(iz_adresa(), false); });
    }

    if (document.readyState === 'loading'){
      document.addEventListener('DOMContentLoaded', zapusk);
    } else { zapusk(); }
  }catch(e){}
})();
/* ===== конец UA-FIXCLICK-V1 ===== */
